package com.truetileplayerindicators;

import net.runelite.client.plugins.playerindicators.PlayerIndicatorsConfig;

public enum TrueTileHighlightMode
{
	INHERIT("Inherit"),
	ALWAYS_ON("Always on"),
	ALWAYS_OFF("Always off");

	private final String label;

	TrueTileHighlightMode(String label)
	{
		this.label = label;
	}

	boolean isEnabled(PlayerIndicatorsConfig.HighlightSetting inherited)
	{
		return this == ALWAYS_ON || (this == INHERIT && inherited == PlayerIndicatorsConfig.HighlightSetting.ENABLED);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

