package com.truetileplayerindicators;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class TrueTilePlayerIndicatorsOverlay extends Overlay
{
	private final Client client;
	private final PlayerHighlightService playerHighlightService;

	@Inject
	TrueTilePlayerIndicatorsOverlay(Client client, PlayerHighlightService playerHighlightService)
	{
		this.client = client;
		this.playerHighlightService = playerHighlightService;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (isPvpActive())
		{
			return null;
		}

		WorldView topLevelWorldView = client.getTopLevelWorldView();
		if (topLevelWorldView == null)
		{
			return null;
		}
		Player localPlayer = client.getLocalPlayer();
		renderWorldView(graphics, topLevelWorldView, localPlayer);
		for (WorldView worldView : topLevelWorldView.worldViews())
		{
			renderWorldView(graphics, worldView, localPlayer);
		}

		return null;
	}

	private void renderWorldView(Graphics2D graphics, WorldView worldView, Player localPlayer)
	{
		for (Player player : worldView.players())
		{
			LocalPoint renderedLocation = player.getLocalLocation();
			if (renderedLocation == null || !worldView.contains(renderedLocation))
			{
				continue;
			}

			TrueTileStyle style = playerHighlightService.getStyle(player, localPlayer);
			if (style == null)
			{
				continue;
			}

			LocalPoint trueTileLocation = getTrueTileLocation(player);
			if (trueTileLocation == null)
			{
				continue;
			}

			Polygon polygon = Perspective.getCanvasTilePoly(client, trueTileLocation);
			if (polygon != null)
			{
				OverlayUtil.renderPolygon(graphics, polygon, style.getHighlightColor(), style.getFillColor(), style.getStroke());
			}
		}
	}

	private boolean isPvpActive()
	{
		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1
			|| client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1;
	}

	static LocalPoint getTrueTileLocation(Player player)
	{
		WorldView worldView = player.getWorldView();
		WorldPoint worldLocation = player.getWorldLocation();
		return worldView == null || worldLocation == null
			? null
			: LocalPoint.fromWorld(worldView, worldLocation);
	}
}

