package com.truetileplayerindicators;

import java.awt.BasicStroke;
import java.awt.Color;
import lombok.Value;

@Value
class TrueTileStyle
{
	Color highlightColor;
	Color fillColor;
	BasicStroke stroke;

	TrueTileStyle(Color highlightColor, Color fillColor, int borderWidth)
	{
		this.highlightColor = highlightColor;
		this.fillColor = fillColor;
		this.stroke = new BasicStroke(Math.max(1, Math.min(TrueTilePlayerIndicatorsConfig.MAX_BORDER_WIDTH, borderWidth)));
	}
}

